def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if isinstance(value, datetime.time):
        return value.strftime("%H:%M:%S.%f")
    elif isinstance(value, str):
        return value
    else:
        raise ValueError("Invalid value type for dehydration")
