def format(self, sql, params):
    if isinstance(params, dict):
        params = list(params.values())
    elif isinstance(params, list):
        params = params
    else:
        raise ValueError("params must be a dict or list")

    out_params = []
    for param in params:
        if isinstance(param, str):
            out_params.append(f"'{param}'")
        elif isinstance(param, int):
            out_params.append(str(param))
        else:
            raise ValueError("params must be a dict or list of strings or integers")

    return sql.format(*out_params), out_params
