def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Check if the inventory is a dictionary
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Check if the inventory has the required keys
    required_keys = ["type", "version", "items"]
    if not all(key in inventory for key in required_keys):
        raise ValueError("Inventory is missing required keys")

    # Check if the type value is valid
    if extract_spec_version:
        type_value = inventory["type"]
        if not isinstance(type_value, str):
            raise ValueError("Type value must be a string")
        if type_value not in self.spec_versions:
            raise ValueError("Invalid type value")
    else:
        type_value = self.spec_version

    # Check if the version value is valid
    version_value = inventory["version"]
    if not isinstance(version_value, str):
        raise ValueError("Version value must be a string")
    if version_value not in self.spec_versions:
        raise ValueError("Invalid version value")

    # Check if the items value is valid
    items_value = inventory["items"]
    if not isinstance(items_value, list):
        raise ValueError("Items value must be a list")
    for item in items_value:
        if not isinstance(item, dict):
            raise ValueError("Item must be a dictionary")
        if not all(key in item for key in required_keys):
            raise ValueError("Item is missing required keys")

    # Check if the item values are valid
    for item in items_value:
        if extract_spec_version:
            item_type_value = item["type"]
            if not isinstance(item_type_value, str):
                raise ValueError("Item type value must be a string")
            if item_type_value not in self.spec_versions:
                raise ValueError("Invalid item type value")
        else:
            item_type_value = type_value

        item_version_value = item["version"]
        if not isinstance(item_version_value, str):
            raise ValueError("Item version value must be a string")
        if item_version_value not in self.spec_versions:
            raise ValueError("Invalid item version value")

    # Check if the item values are valid
    for item in items_value:
        item_items_value = item["items"]
        if not isinstance(item_items_value, list):
            raise ValueError("Item items value must be a list")
        for item_item in item_items_value:
            if not isinstance(item_item, dict):
                raise ValueError("Item item must be a dictionary")
            if not all(key in item_item for key in required_keys):
                raise ValueError("Item item is missing required keys")

    # Check if the item item values are valid
    for item in items_value:
        item_items_value = item["items"]
        for item_item in item_items_value:
            if extract_spec_version:
                item_item_type_value = item_item["type"]
                if not isinstance(item_item_type_value, str):
                    raise ValueError("Item item type value must be a string")
                if item_item_type_value not in self.spec_versions:
                    raise ValueError("Invalid item item type value")
            else:
                item_item_type_value = item_type_value

            item_item_version_value = item_item["version"]
            if not isinstance(item_item_version_value, str):
                raise ValueError("Item item version value must be a string")
            if item_item_version_value not in self.spec_versions:
                raise ValueError("Invalid item item version value")

    # Check if the item item values are valid
    for item in items_value:
        item_items_value = item["items"]
        for item_item in item_items_value:
            item_item_items_value = item_item["items"]
            if not isinstance(item_item_items_value, list):
                raise ValueError("Item item items value must be a list")
            for item_item_item in item_item_items_value:
                if not isinstance(item_item_item, dict):
                    raise ValueError("Item item item must be a dictionary")
                if not all(key in item_item_item for key in required_keys):
                    raise ValueError("Item item item is missing required keys")

    # Check if the item item item values are valid
    for item in items_value:
        item_items_value = item["items"]
