def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Check if version_dirs is a list or tuple
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple")

    # Check if version_dirs is not empty
    if not version_dirs:
        raise ValueError("version_dirs must not be empty")

    # Check if version_dirs is in version sequence
    for i, version_dir in enumerate(version_dirs):
        if not version_dir.isdigit():
            raise ValueError(f"version_dir {version_dir} is not a valid version number")
        if int(version_dir) != i + 1:
            raise ValueError(f"version_dir {version_dir} is not in version sequence")

    # Check if each version has an inventory
    for version_dir in version_dirs:
        inventory_path = os.path.join(self.root_dir, version_dir, "inventory.json")
        if not os.path.isfile(inventory_path):
            raise FileNotFoundError(f"inventory.json not found in {version_dir}")

    # Check if any content digests are different from those in the root inventory
    root_inventory = self.get_root_inventory()
    for version_dir in version_dirs:
        inventory = self.get_inventory(version_dir)
        for content_digest in inventory:
            if content_digest not in root_inventory:
                raise ValueError(f"content digest {content_digest} not found in root inventory")
            if inventory[content_digest] != root_inventory[content_digest]:
                raise ValueError(f"content digest {content_digest} is different in {version_dir}")

    # Return True if all checks pass
    return True

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")
    if not isinstance(bug_ids, list):
        raise ValueError("bug_ids must be a list")
    for bug_id in bug_ids:
        if not isinstance(bug_id, int):
            raise ValueError("bug_ids must be a list of integers")
    for key, value in params.items():
        if not isinstance(key, str):
            raise ValueError("params keys must be strings")
        if not isinstance(value, str):
            raise ValueError("params values must be strings")
    for bug_id in bug_ids:
        params["bug_id"] = bug_id
        result = self.request("bug/%s" % bug_id, "PUT", json=params)
        if "error" in result:
            raise BugsyException(result["message"])
    return params

