def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, iface):
        raise TypeError("Candidate must be an instance of %s" % iface)
    if not hasattr(candidate, "__dict__"):
        raise TypeError("Candidate must have a __dict__ attribute")
    for attr in iface.__dict__:
        if not hasattr(candidate, attr):
            raise TypeError("Candidate is missing attribute %s" % attr)
        if not callable(getattr(candidate, attr)):
            raise TypeError("Attribute %s must be callable" % attr)
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    for base in bases:
        if hasattr(base, "__metaclass__"):
            return base.__metaclass__
    return type

This method takes in a list of bases and an optional explicit metaclass, and returns the metaclass that should be used for the class. If an explicit metaclass is provided, it is returned. Otherwise, the method checks if any of the bases have an attribute named `__metaclass__`, and if so, returns that value. If no explicit metaclass is provided and no bases have a `__metaclass__` attribute, the method returns the built-in `type` class.

