def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    code_block = False
    new_text = ""
    for line in text.splitlines():
        if line.startswith("```"):
            code_block = not code_block
        elif not code_block:
            for word in line.split():
                if word.startswith("#"):
                    tag = word[1:]
                    tags.add(tag)
                    if replacer:
                        new_text += line.replace(tag, replacer(tag))
                    else:
                        new_text += line
                else:
                    new_text += line
    return tags, new_text
